/// Situational conversations ("Real-life Korean") — premium, with the first
/// [freeConversationCount] free as a taster. Situations are the ones
/// visitors and K-culture fans ask about most. Polite 해요체 by default;
/// casual lines are marked as such. Fictional names only, no brand or
/// trademarked names (content policy, spec §3.1).
///
/// Every line and key phrase has a TTS voice slot (voice/phrase/<slotId>),
/// generated by tool/gen_tts_jobs.dart.
library;

class DialogueLine {
  const DialogueLine(
      this.speaker, this.korean, this.romanization, this.english);

  final String speaker;
  final String korean;
  final String romanization;
  final String english;
}

class KeyPhrase {
  const KeyPhrase(this.korean, this.romanization, this.english);

  final String korean;
  final String romanization;
  final String english;
}

class Conversation {
  const Conversation({
    required this.id,
    required this.title,
    required this.titleKo,
    required this.situation,
    required this.lines,
    required this.phrases,
    required this.cultureTip,
  });

  final String id;
  final String title;
  final String titleKo;

  /// One-line scene description shown above the dialogue.
  final String situation;
  final List<DialogueLine> lines;
  final List<KeyPhrase> phrases;
  final String cultureTip;

  String lineSlot(int i) => '${id}_$i';
  String phraseSlot(int i) => '${id}_k$i';
}

